// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 collectAmount, uint256 newMin) internal {
        vm.assume(true);
        try c.Collect(collectAmount) {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMin) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(uint256 collectAmount, uint256 newMin) public {
        _run(collectAmount, newMin);
    }

    receive() external payable { }
}
